# Retry with exponential backoff and full jitter (delays are computed, not slept).
import random

random.seed(7)
BASE, CAP, MAX_ATTEMPTS = 0.5, 8.0, 5

class Transient(Exception):
    pass

calls = {"n": 0}
def flaky_api():
    calls["n"] += 1
    if calls["n"] < 4:                 # fails 3 times, then succeeds
        raise Transient("503")
    return "ok"

def call_with_retry():
    for attempt in range(MAX_ATTEMPTS):
        try:
            return flaky_api()
        except Transient as e:
            ceiling = min(CAP, BASE * 2 ** attempt)   # exponential, capped
            delay = random.uniform(0, ceiling)        # full jitter
            print(f"attempt {attempt + 1} failed ({e}); ceiling {ceiling:.1f}s, wait {delay:.2f}s")
    raise RuntimeError("give up: send to dead-letter queue")

print("result:", call_with_retry(), "after", calls["n"], "calls")
# Worst case total wait is bounded by MAX_ATTEMPTS * CAP.
